nsresult ExchangeFolder::CreateBaseMessageURI(const nsACString& aURI) {
  nsCOMPtr<nsIURI> folderUri;
  nsresult rv =
      NS_NewURI(getter_AddRefs(folderUri), PromiseFlatCString(aURI).Data());
  NS_ENSURE_SUCCESS(rv, rv);

  nsAutoCString scheme;
  rv = folderUri->GetScheme(scheme);
  NS_ENSURE_SUCCESS(rv, rv);

  mExchangeProtocol = scheme;

  nsAutoCString tailURI(aURI);

  // Remove the scheme and the following `:/'.
  nsAutoCString uriRoot(scheme);
  uriRoot.Append(":/");
  if (tailURI.Find(uriRoot) == 0) {
    tailURI.Cut(0, uriRoot.Length());
  }

  if (scheme.EqualsLiteral("ews")) {
    mBaseMessageURI = kEWSMessageRootURI;
  } else if (scheme.EqualsLiteral("graph")) {
    mBaseMessageURI = kGraphMessageRootURI;
  } else {
    return NS_ERROR_UNEXPECTED;
  }

  mBaseMessageURI += tailURI;

  return NS_OK;
}
